messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Humanoid Treadmill Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #1a1a1a; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';

        // --- Configuration ---
        const CYCLE_DURATION = 10; // seconds
        const STAND_TIME = 2;      // seconds
        const WALK_TIME = 3;       // seconds
        const RUN_TIME = 3;        // seconds
        const TOTAL_TIME = 10;     // Must match STAND*2 + WALK + RUN

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(-1, 2.5, 8); // Side-on view
        camera.lookAt(0, 1.5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        scene.add(dirLight);

        // --- Materials ---
        const skinMaterial = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.5 });
        const clothMaterial = new THREE.MeshStandardMaterial({ color: 0x3366cc, roughness: 0.8 });
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x444444, roughness: 0.9 });

        // --- Geometry Helpers ---
        function createLimb(geo) {
            const mesh = new THREE.Mesh(geo, skinMaterial);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        function createCloth(geo) {
            const mesh = new THREE.Mesh(geo, clothMaterial);
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            return mesh;
        }

        // --- Build Humanoid ---
        const humanoid = new THREE.Group();
        scene.add(humanoid);

        // Dimensions
        const legHeight = 1.2;
        const legWidth = 0.3;
        const legDepth = 0.4;
        const armLength = 1.1;
        const armWidth = 0.25;
        const armDepth = 0.3;
        const torsoHeight = 1.4;
        const torsoWidth = 0.6;
        const torsoDepth = 0.5;
        const headRadius = 0.35;

        // Pivot Points (Joints)
        const hipL = new THREE.Group();
        const hipR = new THREE.Group();
        const shoulderL = new THREE.Group();
        const shoulderR = new THREE.Group();

        // Legs
        const legGeo = new THREE.BoxGeometry(legWidth, legHeight, legDepth);
        // Offset geometry so origin is at the top of the leg
        legGeo.translate(0, -legHeight/2, 0); 

        const leftLeg = createLimb(legGeo);
        const rightLeg = createLimb(legGeo);

        // Arms
        const armGeo = new THREE.BoxGeometry(armWidth, armLength, armDepth);
        armGeo.translate(0, -armLength/2, 0);

        const leftArm = createLimb(armGeo);
        const rightArm = createLimb(armGeo);

        // Torso & Head
        const torsoGeo = new THREE.BoxGeometry(torsoWidth, torsoHeight, torsoDepth);
        const torso = createCloth(torsoGeo);
        const headGeo = new THREE.SphereGeometry(headRadius, 8, 6);
        const head = createLimb(headGeo);

        // Assembly
        hipL.position.set(-0.25, 0, 0); // X offset for width
        hipR.position.set(0.25, 0, 0);

        shoulderL.position.set(-0.35, torsoHeight/2, 0);
        shoulderR.position.set(0.35, torsoHeight/2, 0);

        // Add limbs to pivots
        hipL.add(leftLeg);
        hipR.add(rightLeg);
        shoulderL.add(leftArm);
        shoulderR.add(rightArm);

        // Add pivots to humanoid
        humanoid.add(hipL);
        humanoid.add(hipR);
        humanoid.add(shoulderL);
        humanoid.add(shoulderR);

        // Add body parts to pivots
        hipL.add(leftLeg);
        hipR.add(rightLeg);
        shoulderL.add(leftArm);
        shoulderR.add(rightArm);

        // Torso and Head are static children of humanoid
        humanoid.add(torso);
        humanoid.add(head);
        torso.position.y = torsoHeight / 2;
        head.position.y = torsoHeight/2 + headRadius;

        // --- Environment (Treadmill) ---
        const groundGeo = new THREE.BoxGeometry(20, 0.2, 6);
        const ground = new THREE.Mesh(groundGeo, groundMaterial);
        ground.position.y = -0.1;
        ground.receiveShadow = true;
        scene.add(ground);

        // --- Animation Logic ---
        const clock = new THREE.Clock();

        // Helper to map time to angle in radians
        // Phase 0-2: Stand
        // Phase 2-5: Walk
        // Phase 5-8: Run
        // Phase 8-10: Stand

        function getAnimationState(time) {
            const t = time % CYCLE_DURATION;
            if (t < STAND_TIME) return 'stand';
            if (t < STAND_TIME + WALK_TIME) return 'walk';
            if (t < STAND_TIME + WALK_TIME + RUN_TIME) return 'run';
            return 'stand';
        }

        // Calculate angles based on time within the specific phase
        function animateLimb(time, phase, speedMultiplier, maxSwing) {
            let angle = 0;
            if (phase === 'stand') return 0;

            // Calculate progress within the phase
            const phaseStart = phase === 'walk' ? STAND_TIME : STAND_TIME + WALK_TIME;
            const phaseDuration = phase === 'walk' ? WALK_TIME : RUN_TIME;

            const localTime = time - phaseStart;

            // Sine wave for swinging
            // Speed multiplier increases frequency
            const freq = speedMultiplier;
            angle = Math.sin(localTime * freq) * maxSwing;

            return angle;
        }

        function updateAnimation(time) {
            const state = getAnimationState(time);

            // Smooth transitions
            let lLegAngle, rLegAngle, lArmAngle, rArmAngle;
            let leanAngle = 0;

            if (state === 'stand') {
                lLegAngle = 0; rLegAngle = 0;
                lArmAngle = 0; rArmAngle = 0;
            } else if (state === 'walk') {
                // Walking: Opposite arms/legs move together
                // Slower frequency
                const speed = 4.0; 
                lLegAngle = Math.sin(time * speed) * 0.6;
                rLegAngle = -Math.sin(time * speed) * 0.6;

                lArmAngle = -Math.sin(time * speed) * 0.5;
                rArmAngle = Math.sin(time * speed) * 0.5;
            } else if (state === 'run') {
                // Running: Faster, larger swings
                const speed = 8.0;
                lLegAngle = Math.sin(time * speed) * 1.2;
                rLegAngle = -Math.sin(time * speed) * 1.2;

                lArmAngle = -Math.sin(time * speed) * 1.0;
                rArmAngle = Math.sin(time * speed) * 1.0;

                // Forward lean
                leanAngle = THREE.MathUtils.lerp(0, 0.25, Math.abs(Math.sin(time * speed)));
            }

            // Apply rotations
            // Legs rotate around Z axis (forward/back)
            hipL.rotation.z = lLegAngle;
            hipR.rotation.z = rLegAngle;

            // Arms rotate around Z axis
            shoulderL.rotation.z = lArmAngle;
            shoulderR.rotation.z = rArmAngle;

            // Apply Lean to entire humanoid
            humanoid.rotation.z = leanAngle;

            // Subtle bounce for realism
            const bounce = Math.abs(Math.sin(time * 8)) * 0.1;
            humanoid.position.y = bounce;
        }

        // --- Render Loop ---
        function render() {
            const time = clock.getElapsedTime();

            updateAnimation(time);

            renderer.render(scene, camera);
            requestAnimationFrame(render);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        render();
    </script>
</body>
</html>
```
